with metrics as (select *, first_value(dept_name) ignore nulls over (order by budget, id rows between unbounded preceding and current row) as first_known_dept_name, percent_rank() over (partition by location order by budget desc nulls last) as budget_percent_rank, lag(budget, 1) over (order by budget, id) as prev_budget, last_value(dept_name) ignore nulls over (order by budget, id rows between unbounded preceding and current row) as last_known_dept_name, last_value(location) ignore nulls over (order by budget, id rows between unbounded preceding and current row) as last_known_location from departments where location not in ('Tokyo', 'Berlin')) select id, budget, first_known_dept_name, budget_percent_rank, prev_budget, last_known_dept_name, last_known_location from metrics order by prev_budget
